package main

import "fmt"

func main() {
	suma := 0
	n := 1

	for n <= 10 {
		suma += n
		n++
	}

	// 1 + 2 + ... + 10
	fmt.Println(suma) // 55
}

package main

import "fmt"

func main() {
	for i := range 10 {
		if i%2 == 0 {
			continue // salta pares
		}
		if i > 7 {
			break // sale del bucle
		}
		fmt.Println(i)
	}
	// Sale: 1, 3, 5 y 7
}

